"""Render a 12kHz synchronized comparison and supported high-shelf trial."""
from pathlib import Path
import json, re

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'docs/experiments/20261008-iphone-km184-public'
data = json.loads((OUT / 'brightness-extension-browser.json').read_text())
css = re.search(r'<style>(.*?)</style>', (OUT / 'speaker-guitar-confidence-eq.html').read_text(), re.S)[1]
html = r'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>남은 밝기 · 6–10kHz 보완 비교</title><style>__CSS__
.spec img{aspect-ratio:470/280}.imagebox{position:relative;margin-left:36px}.freqtick{position:absolute;left:-35px;width:32px;text-align:right;color:#69808a;font-size:10px;pointer-events:none}.gridline{position:absolute;left:0;right:0;border-top:1px solid #ffffff30;pointer-events:none}.roi{position:absolute;left:0;right:0;border:1px solid #55eee0;background:#55eee015;pointer-events:none;box-sizing:border-box}.axis-title{font-size:.85rem;color:#54727b;margin:5px 0}.low{color:#8d9da3;background:#f0f3f4}.status{padding:10px;border-radius:6px;background:#eaf4f3}.responselegend{display:flex;gap:15px;align-items:center}h3{margin:0 0 8px}.axis{margin-left:36px}</style>
<main><nav><a href="speaker-guitar-confidence-eq.html">앞선 중고역 후보</a><a href="october-four-device-eq.html">네 기기 비교</a><a href="joint-event-timbre-qc.html">사건별 음색 비교</a></nav><h1>보정 후에도 남은 밝기: 더 높은 대역 확인</h1>
<p class="lead">“앞선 시도보다 나아졌지만 아직 밝다”는 청취 결과를 반영했습니다. 앞선 점수의 마지막 중심 대역은 5.08kHz, 스펙트로그램 상단은 6kHz라서 <b>6–10kHz의 차이가 충분히 드러나지 않았습니다.</b> 이번에는 12kHz까지 표시하고, 기타 신호가 충분한 대역에서 밝기와 연결되는 상대 에너지를 확인했습니다.</p>
<div class="panel"><table><thead><tr><th>기기</th><th>6–10kHz 신뢰 창 / 후보 창</th><th>현재 상대 차이 중앙값</th><th>추가 보정 후</th><th>판단</th></tr></thead><tbody id="summary"></tbody></table></div>
<p class="lead"><b>S21:</b> 신뢰 조건을 통과한 91개 창 모두 6–10kHz가 상대적으로 강했습니다. 핑크·화이트·로그 스윕도 같은 방향을 지지합니다. 앞선 후보 뒤에 <b>6kHz 하이셸프, 최대 −6dB</b> 한 단을 더했습니다. 보정 후에도 이 대역의 차이는 남지만, 신뢰 창에서 절대 차이가 0.5dB 넘게 악화된 경우는 0개입니다.</p>
<p class="lead warn"><b>iPhone:</b> 6–10kHz 신뢰 창 45개 중 과다는 1개였고, 화음에서는 오히려 해당 대역 에너지가 작았습니다. 퍼커션의 1.6–3.2kHz는 상대적으로 강합니다. 따라서 iPhone에 같은 하이셸프를 추가하지 않았습니다. 밝은 인상은 총 고역량 외에도 성분 대비·어택·중역 균형과 연결될 수 있어, 그 원인을 아직 확정하지 않습니다.</p>
<h2>실제 필터 응답</h2><p>앞선 청취 후보에 상위 보완을 추가한 응답입니다. S21의 추가 필터는 중저역에서 변화가 작고 높은 주파수에서만 점차 낮아집니다.</p><div class="panel"><svg id="response" viewBox="0 0 860 275" aria-label="앞선 후보와 상위 보완 후보의 주파수 응답"></svg></div>
<h2>주법별 같은 시각 비교</h2><p>네 주법과 기기를 선택해 재생 버튼으로 같은 위치를 전환하세요. 청록색 테두리는 이번에 확인한 6–10kHz입니다. 1.6–3.2kHz와 3.2–6kHz도 표에서 함께 봅니다. 회색 잔차는 약한 신호 구간입니다.</p>
<div class="layout"><div class="side" id="groups"></div><div><div class="devices" id="devices"></div><p id="selected"></p><div id="decision" class="status"></div><div class="panel"><table><thead><tr><th>대역</th><th>양쪽 최소 SNR</th><th>앞선 후보의 상대 과다</th><th>상위 보완 후</th></tr></thead><tbody id="clipmetrics"></tbody></table></div><div class="transport"><button id="toggle">재생 / 정지</button><input id="seek" type="range" min="0" max="5" step="0.01" value="0" aria-label="공통 재생 위치"><span id="time">0.0 / 5.0초</span></div><div id="versions"></div></div></div>
<h2>수치의 의미와 적용 범위</h2><p>표의 상대 과다는 <b>(대상 대역 에너지 / 400–1600Hz 에너지)</b>의 기기−KM184 차이(dB)입니다. 양수는 대상 대역이 상대적으로 강하고, 음수는 약하다는 뜻입니다. 5초 평균이며, 각 성분의 뾰족함이나 순간 어택의 전부를 설명하지는 않습니다. 배경 대비 양쪽 SNR와 대역 에너지 비중으로 신뢰도를 정했고, 보정 전후에는 같은 원본 기반 신뢰도·기준을 사용했습니다. 스펙트로그램과 청취에는 앞선 화면과 같은 원본 기반 레벨 맞춤을 유지했습니다.</p>
<p>현재 분석은 기존 중역 평가에서 선택된 창을 확장한 것이므로 기타 전체를 대표하지는 않습니다. 특히 약한 개방현의 6–10kHz는 배경에 가까워 같은 가중치로 판단하지 않습니다. S21 추가 보정은 11주법의 신뢰 창 중앙값에서 필요한 방향을 구해 최대 −6dB로 제한한 탐색 후보입니다. 기준은 10월 자료이며, 9월은 사용하지 않았습니다.</p>
<p class="muted">S21 전체 연속 처리 샘플 피크는 감쇠 전 약 +2.95dBFS, 4배 오버샘플 근사는 +2.96dBFS입니다. 기존 −6.5dB 출력 감쇠를 유지하면 약 −3.55dBFS의 여유가 있습니다. 청취 파일은 버전 간 공통 안전 배율을 사용합니다. 실제 앱 입출력 지연은 미확인입니다. <a href="brightness-extension-browser.json">필터 계수·대역 근거·창별 기록</a>.</p></main>
<script>const data=__DATA__;const names={arpeggio:'아르페지오',open_notes:'개방현 단음',complex:'복합 화음',percussion:'퍼커션'};const labels={km184:'KM184 기준',raw:'기기 원본',current:'앞선 청취 후보',extended:'앞선 후보 + 6kHz 하이셸프'};let group='complex',device='s21',which='extended',audio=null,pos=0,players={};const seek=document.getElementById('seek');function choice(){return data.clips.find(c=>c.group===group&&c.device===device)}function stop(){if(audio){audio.pause();pos=audio.currentTime||pos;audio=null}}function sync(){if(audio&&!audio.paused)pos=audio.currentTime;seek.value=pos;document.getElementById('time').textContent=pos.toFixed(1)+' / 5.0초';document.querySelectorAll('.cursor').forEach(x=>x.style.left=(pos/5*100)+'%');if(audio&&!audio.paused)requestAnimationFrame(sync)}function play(k,at){const same=audio===players[k]&&!audio.paused;stop();which=k;if(at!==undefined)pos=at;else if(pos>=4.98)pos=0;if(same&&at===undefined){sync();return}const x=players[k];x.currentTime=Math.min(pos,4.98);audio=x;x.play().catch(()=>{});sync()}function frequencyMarks(){const y=f=>Math.log(12000/f)/Math.log(12000/80)*100;return [100,500,1000,2000,4000,6000,10000,12000].map(f=>'<span class="freqtick" style="top:'+y(f)+'%">'+(f>=1000?f/1000+'k':f)+'</span><span class="gridline" style="top:'+y(f)+'%"></span>').join('')+'<span class="roi" style="top:'+y(10000)+'%;height:'+(y(6000)-y(10000))+'%"></span>'}function graph(){let s='<rect width="860" height="275" fill="white"/>';const x=f=>60+Math.log(f/100)/Math.log(16000/100)*740,y=v=>110-v*12;for(const v of [-10,-5,0,5])s+='<line x1="60" x2="800" y1="'+y(v)+'" y2="'+y(v)+'" stroke="'+(v===0?'#8ba0a4':'#e0e8eb')+'"/><text x="12" y="'+(y(v)+4)+'" font-size="13">'+v+'dB</text>';for(const f of [100,500,1000,2000,4000,6000,10000,16000])s+='<text x="'+x(f)+'" y="260" text-anchor="middle" font-size="12">'+(f>=1000?f/1000+'k':f)+'</text>';for(const [k,color] of [['current','#6d8791'],['extended','#078b83']]){if(!data.response_db[device][k])continue;let z=data.response_db[device][k];s+='<polyline points="'+data.response_hz.map((f,i)=>x(f)+','+y(z[i])).join(' ')+'" fill="none" stroke="'+color+'" stroke-width="3"/>'}s+='<text x="95" y="20" fill="#6d8791">앞선 후보</text>';if(device==='s21')s+='<text x="245" y="20" fill="#078b83">S21 상위 보완</text>';document.getElementById('response').innerHTML=s}function render(reset=true){stop();if(reset)pos=0;const c=choice();if(!c.media[which])which='current';document.querySelectorAll('#groups button').forEach(x=>x.setAttribute('aria-selected',x.dataset.group===group));document.querySelectorAll('#devices button').forEach(x=>x.setAttribute('aria-selected',x.dataset.device===device));document.getElementById('selected').textContent=c.label+' · KM184 '+c.start_s+'–'+(c.start_s+5)+'초 · '+device.toUpperCase();document.getElementById('decision').textContent=device==='s21'?'6–10kHz 과다가 반복되어 하이셸프를 시험했습니다. 보정 후에도 차이는 남습니다.':'화음의 전체 고역량은 이미 작아 추가 고역 감쇠를 적용하지 않았습니다. 퍼커션의 중고역 균형을 별도로 봅니다.';let m='';for(let i=2;i<5;i++){let snr=c.joint_snr_db[i];m+='<tr class="'+(snr<10?'low':'')+'"><td>'+data.band_bounds_hz[i].map(v=>(v/1000).toFixed(1)).join('–')+'kHz</td><td>'+snr.toFixed(1)+'dB'+(snr<10?' · 판단 보류':'')+'</td><td>'+c.relative_band_excess_db.current[i].toFixed(2)+'dB</td><td>'+(c.relative_band_excess_db.extended?c.relative_band_excess_db.extended[i].toFixed(2)+'dB':'미적용')+'</td></tr>'}document.getElementById('clipmetrics').innerHTML=m;let box=document.getElementById('versions');box.replaceChildren();players={};for(const k of Object.keys(c.media)){const media=c.media[k],card=document.createElement('div');card.className='panel';card.innerHTML='<h3>'+labels[k]+'</h3><div class="specrow"><div><div class="axis-title">스펙트로그램 · 80Hz–12kHz</div><div class="imagebox"><div class="spec" data-key="'+k+'"><img src="'+media.spectrogram+'" alt="'+labels[k]+' 스펙트로그램"><span class="cursor"></span>'+frequencyMarks()+'</div></div></div><div><div class="axis-title">KM184 대비 잔차 · 파랑 부족 / 빨강 과다</div><div class="imagebox"><div class="spec" data-key="'+k+'">'+(media.residual?'<img src="'+media.residual+'" alt="KM184 대비 잔차"><span class="cursor"></span>'+frequencyMarks():'<p>기준 녹음</p>')+'</div></div></div></div><div class="specrow"><div class="axis"><span>0초</span><span>1초</span><span>2초</span><span>3초</span><span>4초</span><span>5초</span></div><div class="axis"><span>0초</span><span>1초</span><span>2초</span><span>3초</span><span>4초</span><span>5초</span></div></div><button class="play" data-play="'+k+'">'+labels[k]+' 재생</button>';box.append(card);players[k]=new Audio(media.audio);players[k].onended=()=>{audio=null;pos=5;sync()}}box.querySelectorAll('[data-play]').forEach(x=>x.onclick=()=>play(x.dataset.play));box.querySelectorAll('.spec').forEach(x=>x.onclick=e=>{const r=x.getBoundingClientRect();play(x.dataset.key,Math.max(0,Math.min(4.98,(e.clientX-r.left)/r.width*5)))});graph();sync()}document.getElementById('groups').innerHTML=Object.entries(names).map(([g,n])=>'<button data-group="'+g+'">'+n+'</button>').join('');document.querySelectorAll('#groups button').forEach(x=>x.onclick=()=>{group=x.dataset.group;render()});document.getElementById('devices').innerHTML=['iphone','s21'].map(d=>'<button data-device="'+d+'">'+d.toUpperCase()+'</button>').join('');document.querySelectorAll('#devices button').forEach(x=>x.onclick=()=>{device=x.dataset.device;render(false)});seek.oninput=()=>{stop();pos=Number(seek.value);sync()};document.getElementById('toggle').onclick=()=>play(which);let s='';for(const d of ['iphone','s21']){const v=data.summary[d];s+='<tr><td>'+d.toUpperCase()+'</td><td>'+v.reliable_high_windows+' / '+v.candidate_windows+'</td><td>'+v.high_excess_median_db.toFixed(2)+'dB</td><td>'+(d==='s21'?v.high_extended_excess_median_db.toFixed(2)+'dB':'追加 보정 없음')+'</td><td>'+(d==='s21'?'상위 보완 후보':'전체 고역 감쇠 근거 부족')+'</td></tr>'}document.getElementById('summary').innerHTML=s;render()</script></html>'''
html = html.replace('__CSS__', css).replace('__DATA__', json.dumps(data, ensure_ascii=False, separators=(',', ':'))).replace('追加 보정 없음', '추가 보정 없음')
(OUT / 'brightness-extension.html').write_text(html + '\n')
print(OUT / 'brightness-extension.html')
